def bsearch(lst, low, high, x):
    if low > high:
        return -1
    mid = (low + high) // 2
    if lst[mid] == x:
        return mid
    elif lst[mid] > x:
        return bsearch(lst, low, mid - 1, x)
    else:
        return bsearch(lst, mid + 1, high, x)

data = [2, 5, 8, 12, 16, 23, 38, 56, 72, 91]
for i in range(2):
    t = int(input())
    pos = bsearch(data, 0, len(data) - 1, t)
    if pos == -1:
        print(f'{t}不在列表中')
    else:
        print(f'{t}的下标是{pos}')
